export type StaticType = "void" | "bool" | "char" | "int" | "double" | "string" | "error";

/**
 * A symbol as the editor sees it (spec 06 §6.5): enough to fill a dropdown,
 * label a getter block or pick the type of a reporter.
 */
export type SymbolInfo = {
/**
 * The symbol's ID (what blocks store).
 */
id: string,
/**
 * The name the user gave it, as written in its declaring block.
 */
name: string,
/**
 * Its type; for a function, the type it gives back.
 */
type: StaticType,
/**
 * The module that declares it.
 */
module: string,
/**
 * The block that declares it (`var.declare`, `control.for_range`, or the
 * `func.define` of a function and of its parameters).
 */
declBlock: string, } & ({ "kind": "variable",
/**
 * Whether it was declared `const`.
 */
isConst: boolean, } | { "kind": "parameter",
/**
 * How the argument is passed.
 */
mode: PassMode, } | { "kind": "loopVariable" } | { "kind": "function",
/**
 * Its parameters' symbol IDs, in order.
 */
params: Array<string>,
/**
 * The type it gives back (`void` for nothing).
 */
returns: StaticType, });

/**
 * The kind of a `SymbolInfo`, with the details of that kind.
 */
export type SymbolInfoKind = { "kind": "variable",
/**
 * Whether it was declared `const`.
 */
isConst: boolean, } | { "kind": "parameter",
/**
 * How the argument is passed.
 */
mode: PassMode, } | { "kind": "loopVariable" } | { "kind": "function",
/**
 * Its parameters' symbol IDs, in order.
 */
params: Array<string>,
/**
 * The type it gives back (`void` for nothing).
 */
returns: StaticType, };

/**
 * The bundled templates a new project can start from.
 */
export type Template = "empty" | "helloWorld";

/**
 * A compiler toolchain the backend found or the user added.
 */
export type Toolchain = {
/**
 * Its ID (`toolchain_select`).
 */
id: ToolchainId,
/**
 * The g++ version, for example `13.3.0`, when the probe found one.
 */
version: string | null,
/**
 * The target triple, for example `x86_64-linux-gnu`.
 */
target: string | null,
/**
 * The distribution flavour, for example `MSYS2 UCRT64`.
 */
flavor: string | null,
/**
 * Where it is, for display only (the status bar and the toolchain page); it
 * is never accepted back. It is the path the compiler was found as, before
 * links were resolved (for example `/usr/bin/g++`, or the file the user
 * picked), which `toolchains.json` keeps as `foundAs` so that a cached entry
 * shows the same path as a discovered one.
 */
displayPath: string,
/**
 * How it was found.
 */
source: ToolchainSource,
/**
 * Whether it passed every health check and can build.
 */
usable: boolean,
/**
 * Whether it is the selected toolchain.
 */
selected: boolean,
/**
 * What it supports.
 */
capabilities: ToolchainCapabilities,
/**
 * The failed health checks, as `B2C-T1xxx` diagnostics.
 */
problems: Array<Diagnostic>, };

/**
 * The response of `toolchain_add_dialog`.
 */
export type ToolchainAddDialogResponse = { "status": "cancelled" } | { "status": "ok",
/**
 * The added toolchain; when `usable` is false, `problems` says why.
 */
toolchain: Toolchain, };

/**
 * What a toolchain supports.
 */
export type ToolchainCapabilities = {
/**
 * The C++ standards it accepts.
 */
standards: Array<CppStandard>,
/**
 * Whether `std::format` works.
 */
stdFormat: boolean,
/**
 * Whether the address and undefined-behaviour sanitizers work.
 */
sanitizers: boolean,
/**
 * Whether it reports diagnostics as SARIF.
 */
sarif: boolean, };

/**
 * A toolchain in the backend's toolchain list. Stable across restarts: it is
 * derived from the canonical path of the compiler driver.
 */
export type ToolchainId = `tc_${string}`;

/**
 * The response of `toolchain_list` and `toolchain_rescan`.
 */
export type ToolchainListResponse = {
/**
 * The toolchains, in discovery order.
 */
toolchains: Array<Toolchain>,
/**
 * Whether background discovery is still running; a `toolchainsUpdated` app
 * event follows when it finishes.
 */
discovering: boolean, };

/**
 * The request of `toolchain_select`: make a toolchain the default.
 */
export type ToolchainSelectRequest = {
/**
 * The toolchain.
 */
toolchainId: ToolchainId, };

/**
 * The selected toolchain.
 */
export type ToolchainSettings = {
/**
 * The selected toolchain, or `null` for the first usable one in discovery
 * order.
 */
selectedId: ToolchainId | null, };

/**
 * The response of `toolchain_setup_info`: what the setup page needs to suggest
 * an install command.
 */
export type ToolchainSetupInfo = {
/**
 * The operating system.
 */
platform: Platform,
/**
 * Whether no usable toolchain was found.
 */
noUsableToolchain: boolean,
/**
 * The Linux distribution, when it could be read; `null` on Windows.
 */
distro: Distro | null, };

/**
 * How a toolchain was found. `toolchains.json` stores the same value with
 * each cached toolchain (`docs/spec/05-project-format.md` §5.9), so a
 * cached entry reports the source that discovery gives it.
 */
export type ToolchainSource = "path" | "wellKnown" | "manual";

/**
 * A project's trust state.
 */
export type Trust = {
/**
 * Trusted or restricted.
 */
state: TrustState,
/**
 * Why it is trusted; `null` when restricted.
 */
source: TrustSource | null,
/**
 * Why it is restricted; `null` when trusted.
 */
restrictedReason: RestrictedReason | null,
/**
 * Whether the file carries the Windows Mark of the Web (downloaded from the
 * Internet), which makes the trust dialog warn more strongly.
 */
markOfTheWeb: boolean, };

/**
 * The request of `trust_get`.
 */
export type TrustGetRequest = {
/**
 * The project.
 */
handle: Handle, };

/**
 * The request of `trust_grant`: ask the user, in a native dialog, whether to
 * trust the project or its folder.
 */
export type TrustGrantRequest = {
/**
 * The project.
 */
handle: Handle, };

/**
 * The response of `trust_get`, `trust_grant` and `trust_revoke`.
 */
export type TrustResponse = {
/**
 * The project's trust state after the call.
 */
trust: Trust, };

/**
 * The request of `trust_revoke`: forget the project's trust record.
 */
export type TrustRevokeRequest = {
/**
 * The project.
 */
handle: Handle, };

/**
 * Why a project is trusted.
 */
export type TrustSource = "createdHere" | "project" | "folder";

/**
 * Whether a project may be built and run.
 */
export type TrustState = "trusted" | "restricted";
